view_spec.config:
{
  "view": {
    "type": "view.list",
    "items": [
      {
        "type": "helper.if",
        "condition": {
          "type": "condition.equals",
          "data": {
            "type": "data.input",
            "path": "mode"
          },
          "to": "classification_training"
        },
        "then": {
          "type": "view.text",
          "content": "Попробуйте разметить фотографию: выделите каждую взрослую бабочку отдельной рамкой и выберите ответ."
        },
        "else": {
          "type": "view.text",
          "content": "Осмотрите весь кадр. Выделите каждую взрослую бабочку, включая видимые усики и лапки."
        }
      },
      {
        "type": "helper.if",
        "condition": {
          "type": "condition.equals",
          "data": {
            "type": "data.input",
            "path": "mode"
          },
          "to": "classification_training"
        },
        "then": {
          "type": "field.image-annotation",
          "image": {
            "type": "data.input",
            "path": "image"
          },
          "data": {
            "type": "data.internal",
            "path": "practice_regions",
            "default": []
          },
          "shapes": {
            "rectangle": true
          },
          "fullHeight": true,
          "validation": {
            "type": "condition.all",
            "conditions": [
              {
                "type": "condition.any",
                "conditions": [
                  {
                    "type": "condition.not",
                    "condition": {
                      "type": "condition.equals",
                      "data": {
                        "type": "data.output",
                        "path": "status"
                      },
                      "to": "HAS_BUTTERFLY"
                    }
                  },
                  {
                    "type": "condition.not",
                    "condition": {
                      "type": "condition.empty",
                      "data": {
                        "type": "data.internal",
                        "path": "practice_regions",
                        "default": []
                      }
                    }
                  }
                ],
                "hint": "Нарисуйте рамку для каждой бабочки."
              },
              {
                "type": "condition.any",
                "conditions": [
                  {
                    "type": "condition.not",
                    "condition": {
                      "type": "condition.equals",
                      "data": {
                        "type": "data.output",
                        "path": "status"
                      },
                      "to": "NO_BUTTERFLY"
                    }
                  },
                  {
                    "type": "condition.empty",
                    "data": {
                      "type": "data.internal",
                      "path": "practice_regions",
                      "default": []
                    }
                  }
                ],
                "hint": "Для ответа «Бабочек нет» удалите все рамки."
              }
            ]
          }
        },
        "else": {
          "type": "field.image-annotation",
          "image": {
            "type": "data.input",
            "path": "image"
          },
          "data": {
            "type": "data.output",
            "path": "result",
            "default": []
          },
          "shapes": {
            "rectangle": true
          },
          "fullHeight": true,
          "validation": {
            "type": "condition.all",
            "conditions": [
              {
                "type": "condition.any",
                "conditions": [
                  {
                    "type": "condition.not",
                    "condition": {
                      "type": "condition.equals",
                      "data": {
                        "type": "data.output",
                        "path": "status"
                      },
                      "to": "HAS_BUTTERFLY"
                    }
                  },
                  {
                    "type": "condition.not",
                    "condition": {
                      "type": "condition.empty",
                      "data": {
                        "type": "data.output",
                        "path": "result",
                        "default": []
                      }
                    }
                  }
                ],
                "hint": "Нарисуйте рамку для каждой бабочки."
              },
              {
                "type": "condition.any",
                "conditions": [
                  {
                    "type": "condition.not",
                    "condition": {
                      "type": "condition.equals",
                      "data": {
                        "type": "data.output",
                        "path": "status"
                      },
                      "to": "NO_BUTTERFLY"
                    }
                  },
                  {
                    "type": "condition.empty",
                    "data": {
                      "type": "data.output",
                      "path": "result",
                      "default": []
                    }
                  }
                ],
                "hint": "Для ответа «Бабочек нет» удалите все рамки."
              }
            ]
          }
        }
      },
      {
        "type": "field.radio-group",
        "data": {
          "type": "data.output",
          "path": "status"
        },
        "options": [
          {
            "value": "HAS_BUTTERFLY",
            "label": "Бабочки есть"
          },
          {
            "value": "NO_BUTTERFLY",
            "label": "Бабочек нет"
          },
          {
            "value": "UNSURE",
            "label": "Не уверен — нужен разбор"
          },
          {
            "value": "IMAGE_ERROR",
            "label": "Изображение не загрузилось"
          }
        ],
        "validation": {
          "type": "condition.required",
          "hint": "Выберите один ответ."
        }
      }
    ]
  },
  "plugins": [
    {
      "type": "plugin.toloka",
      "layout": {
        "kind": "scroll",
        "taskWidth": 1000
      }
    }
  ]
}
